var o=[{title:`Rango pasivo y activo`,text:`Quizá puedas mover el brazo por encima de la cabeza con ayuda, pero te cueste levantarlo hasta ahí por ti mismo. Eso indica que tienes flexibilidad suficiente sin la misma fuerza o coordinación en ese rango. Otras personas tienen un rango cómodo realmente limitado y pueden beneficiarse de estiramientos graduales o de otra variante del ejercicio.`},{title:`Prueba los movimientos que usas`,text:`Un alcance controlado por encima de la cabeza, una sentadilla cómoda con el peso corporal o una bisagra de cadera pueden mostrar si un movimiento de tu entrenamiento se siente restringido. Compara los lados, pero no los fuerces a coincidir. Se trata de detectar un límite práctico. No diagnostica la causa de la rigidez, del dolor articular ni de una afección médica.`},{title:`Entrena el control en el rango que tienes`,text:`Los círculos dinámicos de brazos, las zancadas controladas, las rotaciones torácicas y los movimientos lentos de cadera te permiten practicar rangos con control activo. Los ejercicios de fuerza hechos en un rango cómodo y progresados con el tiempo también pueden mejorar la movilidad. El estiramiento estático mejora la flexibilidad, pero por sí solo no siempre desarrolla el control.`},{title:`No hay un único rango perfecto`,text:`Las proporciones corporales, la estructura de las articulaciones, el historial de lesiones y la habilidad influyen en qué movimientos resultan cómodos. No necesitas una sentadilla profunda máxima ni una flexibilidad extrema del hombro para entrenar bien. Elige un rango en el que tu técnica se mantenga estable y sin dolor, y construye desde ahí poco a poco.`},{title:`Cómo usar TrainUp`,text:`Si una zona del cuerpo limita tu rango, añádela como limitación en Perfil, con una nota. El plan elige entonces ejercicios que encajan con tus limitaciones, tu nivel y tu coordinación. Cada página de ejercicio en Ejercicios tiene pasos y notas de técnica. Consulta a un médico o a un fisioterapeuta sobre una restricción que persista, un dolor sin explicación o síntomas que afecten a tu vida diaria.`}];var i=[{label:`ACE 2026: movilidad frente a flexibilidad`,url:`https://www.acefitness.org/continuing-education/certified/may-2026/9119/mobility-vs-flexibility-why-the-difference-matters-for-movement-and-performance/`},{label:`ACE 2026: guía práctica sobre estiramientos`,url:`https://www.acefitness.org/continuing-education/certified/april-2026/9104/new-expert-guidance-on-stretching-what-belongs-in-your-programs/?authorScope=80`},{label:`Declaración de posición del ACSM de 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var n={sections:o,sources:i};export{n as default,o as sections,i as sources};